let fields = p.fields();
    // A device whose conversion or 16-bit arithmetic is measured to be Metal's keeps it.
    let measured = p.takes_driver_deviation(crate::error::DriverDeviation::MetalHalfConversion)
        || p.takes_driver_deviation(crate::error::DriverDeviation::MetalHalfArithmetic);
    fields.half_chains == crate::device::HalfChainPolicy::AtExits
        && !measured
        && fields.leaf.float16
        && !fields.float_controls.f16.denorm_preserve
        && quantize_form(p) == QuantizeForm::Converted

let float16 = p.fields().leaf.float16;
    let folds = (p.fields().workarounds).contains(&DriverWorkaround::HalfConversionPairFolded);
    if half_controls(p) && !folds {
        QuantizeForm::Controlled
    } else if float16 {
        QuantizeForm::Converted
    } else {
        QuantizeForm::Device
    }

let fc = p.fields().float_controls;
    let half = fc.f16;
    if !(half.rounding_rte && half.denorm_preserve && half.signed_zero_inf_nan_preserve) {
        return None;
    }
    let mut modes = vec![
        ExecMode::RoundingModeRte { width: 16 },
        ExecMode::DenormPreserve { width: 16 },
        ExecMode::SignedZeroInfNanPreserve { width: 16 },
    ];
    match fc.rounding_independence {
        Independence::All => {}
        Independence::Only32Bit if fc.f64.rounding_rte => {
            modes.push(ExecMode::RoundingModeRte { width: 64 });
        }
        Independence::None if fc.f32.rounding_rte && fc.f64.rounding_rte => {
            modes.push(ExecMode::RoundingModeRte { width: 32 });
            modes.push(ExecMode::RoundingModeRte { width: 64 });
        }
        Independence::Only32Bit | Independence::None => return None,
    }
    match fc.denorm_independence {
        Independence::All => {}
        Independence::Only32Bit if fc.f64.denorm_preserve => {
            modes.push(ExecMode::DenormPreserve { width: 64 });
        }
        Independence::Only32Bit | Independence::None => return None,
    }
    Some(modes)

if p.takes_driver_deviation(DriverDeviation::MetalHalfFma) && p.fields().leaf.float16 {
        Route::F16
    } else if p.fields().leaf.fma16 && narrow::half_controls(p) {
        Route::F16Khr
    } else {
        Route::Native
